"""Citation validation engine: verifies citations against retrieved context and extracts provenance."""
import re
from typing import List, Dict, Any, Tuple
from app.schemas.chat import CitationItem
import logging

logger = logging.getLogger("knowledgevault.citations")


class CitationValidator:
    """Validates citations generated by LLM and maps them to verifiable document provenance."""

    CITATION_PATTERN = re.compile(r"\[cite:(?:([^:\]]+):)?([^\]]+)\]")
    INSUFFICIENT_EVIDENCE_PHRASES = [
        "insufficient evidence",
        "do not contain sufficient information",
        "does not contain sufficient information",
        "not mentioned in the provided documents",
        "cannot be answered from the provided documents",
        "no information provided",
    ]

    @classmethod
    def validate_and_format(
        cls,
        raw_text: str,
        retrieved_chunks: List[Dict[str, Any]]
    ) -> Tuple[str, List[CitationItem], str]:
        """
        Scan raw LLM output for citation tags [cite:doc_id:chunk_id] or [cite:chunk_id],
        validate against retrieved_chunks, replace with clean footnotes [1], [2],
        and extract verifiable provenance.
        Returns: (cleaned_text, valid_citations, confidence_level)
        """
        # Map chunks by chunk_id and index
        chunk_lookup: Dict[str, Dict[str, Any]] = {}
        for c in retrieved_chunks:
            cid = c.get("chunk_id", "")
            chunk_lookup[cid] = c

        matches = list(cls.CITATION_PATTERN.finditer(raw_text))
        citation_map: Dict[str, int] = {}
        valid_citations: List[CitationItem] = []
        hallucinated_count = 0

        # Check for insufficient evidence declarations
        text_lower = raw_text.lower()
        is_insufficient = any(phrase in text_lower for phrase in cls.INSUFFICIENT_EVIDENCE_PHRASES)

        for match in matches:
            full_match = match.group(0)
            chunk_id = match.group(2).strip()

            if chunk_id in chunk_lookup:
                if chunk_id not in citation_map:
                    citation_idx = len(citation_map) + 1
                    citation_map[chunk_id] = citation_idx

                    target_chunk = chunk_lookup[chunk_id]
                    meta = target_chunk.get("metadata", {})
                    doc_title = meta.get("document_title") or target_chunk.get("document_title") or "Document"
                    page_num = meta.get("page_number") or target_chunk.get("page_number")
                    doc_id = target_chunk.get("document_id") or meta.get("document_id") or ""
                    
                    # Clean excerpt snippet (~250 chars)
                    content = target_chunk.get("content", "").strip()
                    excerpt = content[:250] + "..." if len(content) > 250 else content

                    valid_citations.append(CitationItem(
                        citation_id=f"[{citation_idx}]",
                        document_id=doc_id,
                        document_title=doc_title,
                        chunk_id=chunk_id,
                        page_number=page_num,
                        excerpt=excerpt,
                        score=float(target_chunk.get("score", 0.0))
                    ))
            else:
                hallucinated_count += 1
                logger.warning("Rejected hallucinated citation: %s", full_match)

        # Replace citation tags in text with clean footnotes
        def replace_tag(match):
            cid = match.group(2).strip()
            if cid in citation_map:
                return f" [{citation_map[cid]}]"
            return ""  # Strip hallucinated citation tags cleanly

        cleaned_text = cls.CITATION_PATTERN.sub(replace_tag, raw_text)
        # Clean up any duplicate spaces created by stripping
        cleaned_text = re.sub(r" +", " ", cleaned_text).strip()

        # Determine confidence
        if is_insufficient:
            confidence = "insufficient_evidence"
        elif len(valid_citations) >= 2 and hallucinated_count == 0:
            confidence = "high"
        elif len(valid_citations) >= 1:
            confidence = "medium"
        else:
            confidence = "low"

        return cleaned_text, valid_citations, confidence
